const removed = new Set(CROMWARK_REMOVED_SETTLEMENT_IDS);
export const cromwarkSettlementRemoved = (id) => CROMWARK_ON && removed.has(id);
// Keep the city rendered and on the map, but never roll a new errand or birth inside its seal.
export const cromwarkQuestSiteBlocked = id => cromwarkSettlementRemoved(id) || (CROMWARK_ON && id === CROMWARK_CITY.mapId);

const filtered = new WeakMap();
/** Keep archive indices stable; names/IDs no longer advertise vanished destinations. */
export function filterCromwarkSettlementLookups(region, regionIndex = 16) {
  if (!CROMWARK_ON || regionIndex !== 16) return;
  const was = filtered.get(region);
  if (was?.count === region.locationCount && was.names === region.mapNameLookup && was.ids === region.mapIdLookup && was.table === region.mapTable) return;
  for (const [name, index] of region.mapNameLookup) {
    if (cromwarkSettlementRemoved(region.mapTable[index]?.mapId)) region.mapNameLookup.delete(name);
  }
  for (const id of region.mapIdLookup.keys()) if (cromwarkSettlementRemoved(id)) region.mapIdLookup.delete(id);
  // Classic contains duplicate names. If the first was retired, a retained namesake remains findable.
  for (let i = 0; i < region.mapNames.length; i++) {
    if (!cromwarkSettlementRemoved(region.mapTable[i]?.mapId) && !region.mapNameLookup.has(region.mapNames[i])) region.mapNameLookup.set(region.mapNames[i], i);
  }
  filtered.set(region, { count: region.locationCount, names: region.mapNameLookup, ids: region.mapIdLookup, table: region.mapTable });
}
